} @Override public boolean equals(Object obj){ //check of obj is null if(obj == null){ return false; } // check if they are the same instance if(this == obj){ return true; } // check if obj is same type if(!(obj instanceof IntTuple)){ return false; } // cast to same type IntTuple tuple = (IntTuple)obj; // check if all fields are the same return tuple.first == this.first && tuple.second == this.second; } When a player makes a guess, the program should respond with one of the four cardinal directions: "North", "South", "East", "West", indicating the direction of the hidden item from the guess. For simplicity, the program will only respond "North" or "South" if the player's guess is not on the same row, or x coordinate, as the location, and "East" or "West" only if the player's guess is on the same row as the location. If the player guesses correctly, simply print "Found!" and terminate the program. If the player repeats a guess, the program should print "Repeat!" instead of a cardinal direction.
